<?php require __DIR__.'/../config/config.php';$u=login_required();if(!has_moderation_consent($pdo,(int)$u['id']))json_out(['error'=>'Please accept the RAAZ privacy and moderation notice in the dashboard first.'],403);clean_expired($pdo);$s=$pdo->prepare("SELECT c.id, x.id peer_id,x.username,x.full_name,x.profile_picture,(SELECT body FROM messages m WHERE m.conversation_id=c.id ORDER BY m.id DESC LIMIT 1) last_message,(SELECT COUNT(*) FROM messages m WHERE m.conversation_id=c.id AND m.sender_id<>? AND m.read_at IS NULL) unread FROM conversations c JOIN conversation_members mine ON mine.conversation_id=c.id AND mine.user_id=? JOIN conversation_members other ON other.conversation_id=c.id AND other.user_id<>? JOIN users x ON x.id=other.user_id ORDER BY c.id DESC");$s->execute([$u['id'],$u['id'],$u['id']]);json_out($s->fetchAll());